-- People, monsters and shortcuts of the arc (fixed ids; the entity trigger fills realm_actors / realm_objects).
select eldervale_private.quest_arc_entities($j$[{"id":"a3c0a000-0003-4000-8000-000000000001","data":{"kind":"npc","name":"Forgemistress Oriel Kade","role":"smith","weapon":"battleaxe","attackType":"hammer","color":5789029,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"The Anvilhall of Emberspire. Best heat in Eldervale.\nDo not ask where it comes from. Nobody ever does.","template":"smith","x":262,"z":198,"yaw":0,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:kade"}},{"id":"a3c0a000-0003-4000-8000-000000000002","data":{"kind":"npc","name":"Nix Calloway the Apprentice","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Apprentice third class. I sweep, I pump the bellows, I occasionally set my eyebrows on fire.","template":"villager","x":271,"z":204,"yaw":-90,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:nix"}},{"id":"a3c0a000-0003-4000-8000-000000000003","data":{"kind":"npc","name":"Tamber the Kindled","role":"mage","weapon":null,"attackType":"magic","color":6312331,"level":18,"hp":65,"damage":13,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Every flame remembers where it was born.\nEmberspire’s flames were born in chains.","template":"mage","x":205,"z":150,"yaw":90,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:tamber"}},{"id":"a3c0a000-0003-4000-8000-000000000004","data":{"kind":"npc","name":"Assayer Doran Pike","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"Ore, ash and assay. I can tell you what anything is made of. People rarely like the answer.","template":"villager","x":249,"z":224,"yaw":180,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:pike"}},{"id":"a3c0a000-0003-4000-8000-000000000005","data":{"kind":"npc","name":"Kessa Emberly","role":"resident","weapon":null,"attackType":"punch","color":8356955,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"I said the oath. I meant some of it.","template":"villager","x":312,"z":124,"yaw":90,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:kessa"}},{"id":"a3c0a000-0003-4000-8000-000000000006","data":{"kind":"npc","name":"The Emberwright’s Ember","role":"mage","weapon":null,"attackType":"magic","color":6312331,"level":18,"hp":65,"damage":13,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"(A voice like a bellows breathing, very slowly.) Small one. You came down into the warm.","template":"mage","x":3062,"z":3006,"yaw":-90,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:ember"}},{"id":"a3c0a000-0003-4000-8000-000000000007","data":{"kind":"npc","name":"Ashwright Quartermaster Sorrel","role":"merchant","weapon":"dagger","attackType":"stab","color":10253389,"level":5,"hp":45,"damage":4,"attackSpeed":2.4,"roam":0,"respawn":30,"attackable":false,"hostile":false,"scale":1,"dialogue":"The Kindled Forge sells to those it trusts. That list is short, and you are on it.","template":"merchant","x":3020,"z":3404,"yaw":180,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:ashwright","shop":{"runiteBar":{"buy":3000,"sell":900,"stock":8},"adamantBar":{"buy":900,"sell":270,"stock":20},"blacksteelBar":{"buy":420,"sell":120,"stock":30},"embersteelArrowtips":{"buy":40,"sell":12,"stock":300},"coal":{"buy":40,"sell":12,"stock":200}}}},{"id":"a3c0a000-0003-4000-9000-000000000001","data":{"kind":"monster","name":"Kindled zealot","species":"human","attackType":"slash","level":12,"hp":140,"damage":2,"attackSpeed":2.6,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1,"weapon":"blacksteelScimitar","template":"bandit","x":226,"z":170,"yaw":0,"maxHit":24,"attackLevel":12,"strengthLevel":10,"defenceLevel":8,"magicLevel":4,"attackBonus":4,"defenceBonuses":{"stab":3,"slash":3,"crush":4,"magic":3,"ranged":3},"xpReward":98,"goldReward":22,"look":{"skin":"#a8714d","hair":"Bald","beard":"Beard","hairColor":"#211b18"},"gear":["rangerHood1","rangerTunic1","rangerTrousers1","rangerBracers1"],"examine":"Ash on the forehead, salt in the pockets.","loot":[{"item":"custom_qa_kindled_sigil","min":1,"max":1,"chance":1,"always":true},{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:zealot"}},{"id":"a3c0a000-0003-4000-9000-000000000002","data":{"kind":"monster","name":"Ash-fed ember hound","species":"wolf","attackType":"fire","level":35,"hp":345,"damage":4,"attackSpeed":2,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1.2,"template":"wolf","x":335,"z":252,"yaw":0,"maxHit":52,"attackLevel":32,"strengthLevel":33,"defenceLevel":28,"magicLevel":11,"attackBonus":11,"defenceBonuses":{"stab":9,"slash":9,"crush":11,"magic":7,"ranged":11},"xpReward":569,"goldReward":83,"tint":8007458,"eyes":16757575,"breath":16738858,"spikes":true,"accent":2759188,"examine":"Someone has been feeding it coal. It liked it.","loot":[{"item":"bones","min":1,"max":1,"chance":1,"always":true}],"behavior":"wander","questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:hound1"}},{"id":"a3c0a000-0003-4000-9000-000000000003","data":{"kind":"monster","name":"Ash-fed ember hound","species":"wolf","attackType":"fire","level":35,"hp":345,"damage":4,"attackSpeed":2,"roam":2,"respawn":60,"attackable":true,"hostile":true,"scale":1.2,"template":"wolf","x":341,"z":258,"yaw":0,"maxHit":52,"attackLevel":32,"strengthLevel":33,"defenceLevel":28,"magicLevel":11,"attackBonus":11,"defenceBonuses":{"stab":9,"slash":9,"