ard":1109,"tint":2759960,"eyes":16765562,"accent":16757575,"examine":"The Herald, rebuilt by the Kindled Forge for anyone who wants a harder day. Harder mode.","loot":[{"item":"runiteBar","min":1,"max":3,"chance":0.4},{"item":"coal","min":10,"max":25,"chance":1,"always":true},{"item":"runiteOre","min":2,"max":4,"chance":0.4},{"item":"coal","min":2,"max":5,"chance":1,"always":true}],"behavior":"wander","questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:reforged","aura":16757575,"crown":true}},{"id":"a3c0a000-0003-4000-a000-000000000001","data":{"kind":"object","name":"Kindled Forge anvil","scale":1,"level":1,"hp":1,"damage":0,"attackSpeed":2.4,"roam":0,"respawn":0,"attackable":false,"hostile":false,"template":"anvil","x":3026,"z":3396,"yaw":0,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:anvil"}},{"id":"a3c0a000-0003-4000-a000-000000000002","data":{"kind":"object","name":"Kindled Forge furnace","scale":1,"level":1,"hp":1,"damage":0,"attackSpeed":2.4,"roam":0,"respawn":0,"attackable":false,"hostile":false,"template":"furnace","x":3017,"z":3396,"yaw":0,"questArc":"forge","blueprint":"quest-arcs-v1","blueprintKey":"forge:furnace"}}]$j$::jsonb);

-- Quests (validated by quest_v2_check; edit them later in the Game console › Quests).
select eldervale_private.quest_arc_put('a3c0b000-0003-4000-8000-000000000001',$q${"chain":"arc-forge","order":1,"published":true,"objectives":[],"key":"arc-forge-1","name":"Sparks in the Ashpit","questPoints":1,"difficulty":"Novice","length":"Short","giver":"a3c0a000-0003-4000-8000-000000000001","icon":"bronzeBar","description":"Someone is salting the quench barrels of the Anvilhall in Emberspire, cracking blade after blade. Forgemistress Kade wants the saboteur found.","dialogue":{"offer":[{"who":"npc","text":"Three blades cracked in the quench this week. Three! My grandmother’s grandmother never cracked three in a lifetime."},{"who":"npc","text":"Someone is pouring ash-salt into my barrels. I want them found, and I want them to explain themselves to my hammer."},{"who":"npc","text":"Start with Nix, my apprentice. He sleeps in the forge loft. If anyone saw something, it was him, probably while sleepwalking."}],"progress":[{"who":"npc","text":"Found my salter yet? My hammer is getting impatient. So am I."}],"complete":[{"who":"npc","text":"The Kindled. Those ash-smeared prophets from the scrubland. Of course."},{"who":"npc","text":"New tools, too. You have a decent hand for bronze. Take this."}]},"stages":[{"id":"nix","journal":"Forgemistress Oriel Kade of the Anvilhall in Emberspire told me someone is salting her quench barrels. Her apprentice Nix sleeps in the forge loft and may have seen something.","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000002","amount":1,"label":"Ask Nix the apprentice what he saw","dialogue":[{"who":"npc","text":"I saw nothing! I was asleep. Well. Mostly. There were people in robes by the barrels, with ash on their faces."},{"who":"npc","text":"They went off towards the old ash pits west of town. I did not follow them. I am an apprentice, not an idiot. Mostly."}]}]},{"id":"pits","journal":"Nix saw robed people with ash-smeared faces by the barrels at night, heading for the old ash pits west of Emberspire.","objectives":[{"type":"visit","x":228,"z":172,"radius":5,"amount":1,"label":"Search the old ash pits west of Emberspire"}]},{"id":"zealot","journal":"At the ash pits a Kindled zealot was filling sacks with ash-salt. He drew a knife rather than talk.","onEnter":{"cutscene":"pits"},"objectives":[{"type":"kill","target":"a3c0a000-0003-4000-9000-000000000001","amount":1,"label":"Stop the Kindled zealot"},{"type":"have","target":"custom_qa_kindled_sigil","amount":1,"label":"Take the zealot’s brass sigil"}]},{"id":"tools","journal":"The zealot wore a brass flame: the sigil of the Kindled, a fire-cult from the scrubland. The salt has ruined Kade’s quench tongs, so I should bring her two bronze bars along with the sigil.","objectives":[{"type":"have","target":"custom_qa_kindled_sigil","amount":1,"label":"Show Kade the Kindled sigil"},{"type":"collect","target":"bronzeBar","amount":2,"label":"Bring Kade two bronze bars for new tongs"}]}],"cutscenes":{"pits":{"name":"The ash pits","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000002","distance":5,"height":2.2,"angle":30}},{"title":"The ash pits","subtitle":"West of Emberspire","ms":2400},{"say":{"who":"npc","name":"Nix Calloway","text":"(Nix’s voice, from a safe distance) Are they there? Are they big? Never mind, I can hear the knife from here."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000002","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"sigil":{"name":"The Kindled","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000001","distance":5,"height":2.2,"angle":30}},{"title":"A brass flame","subtitle":"The Anvilhall, Emberspire","ms":2400},{"say":{"who":"npc","name":"Forgemistress Oriel Kade","text":"The Kindled say our fires are stolen. Stolen from whom, I always ask. They never give a straight answer."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000001","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"sigil"},"journalDone":"I caught a Kindled zealot salting the Anvilhall’s quench barrels at the ash pits west of Emberspire and brought Forgemistress Kade his brass sigil, and bronze for new tongs.","gold":150,"xp":{"smithing":1500,"mining":1000},"lamps":[{"perLevel":10,"minLevel":5,"label":"Quench lamp"}],"unlocks":[{"type":"flag","id":"forge.salter_caught","label":"The Anvilhall’s quench runs clean"},{"type":"dialogue","id":"dialogue.forge-nix-1","label":"Nix the brave","npc":"a3c0a000-0003-4000-8000-000000000002","lines":[{"who":"npc","text":"I have told everyone I helped catch the salter. I have described my part as “crucial”. Please do not correct me."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0003-4000-8000-000000000002',$q${"chain":"arc-forge","order":2,"published":true,"objectives":[],"key":"arc-forge-2","name":"The Kindled Word","questPoints":2,"difficulty":"Intermediate","length":"Medium","giver":"a3c0a000-0003-4000-8000-000000000001","icon":"custom_qa_kindled_sigil","requirements":{"quests":["arc-forge-1"],"skills":{"smithing":{"level":20,"boostable":false},"mining":{"level":20,"boostable":false}}},"description":"The Kindled preach that Emberspire’s fires are stolen. Kade wants someone to wear the brass flame, walk into their shrine, and find out what they are planning.","dialogue":{"offer":[{"who":"npc","text":"A cult that salts barrels is a cult that plans something bigger. I want to know what."},{"who":"npc","text":"Wear that sigil. Walk into their shrine in the scrubland like you belong. Listen. Do not, under any circumstances, swear anything."}],"progress":[{"who":"npc","text":"Anything from the shrine? Do not tell me you joined. You joined. Did you join?"}],"complete":[{"who":"npc","text":"A golem to blow a sleeping god awake. Under my town. Under my forge."},{"who":"npc","text":"...Pike will want to assay this. I think I would rather not know. Thank you."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"swore_oath":true},"lines":[{"who":"npc","text":"You swore their oath. I told you not to swear anything. I said “under any circumstances”. I was very clear."},{"who":"npc","text":"...But Kessa trusts you because of it, so. Fine. Thank you."}]}],"stages":[{"id":"shrine","journal":"Forgemistress Kade asked me to wear the Kindled sigil and walk into the cult’s Cinder Shrine in the scrubland north-west of Emberspire, and listen.","objectives":[{"type":"have","target":"custom_qa_kindled_sigil","amount":1,"label":"Wear the Kindled sigil openly"},{"type":"visit","x":208,"z":153,"radius":5,"amount":1,"label":"Walk into the Cinder Shrine"}]},{"id":"tamber","journal":"The shrine is a ring of blackened stones around a fire that never goes out. The Kindled’s prophet, Tamber, wants to speak with the newcomer.","npc":"a3c0a000-0003-4000-8000-000000000003","onEnter":{"cutscene":"shrine"},"objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000003","amount":1,"label":"Listen to Tamber the Kindled","dialogue":[{"who":"npc","text":"A new spark. Sit. Hear the truth the Anvilhall pays to forget."},{"who":"npc","text":"Beneath Emberspire sleeps the Emberwright, the fire that made the first forge. A hundred years ago the forgemasters chained it and drank its heat. Every blade in Emberspire is borrowed."},{"who":"npc","text":"The debt comes due. Bring an offering to the fire, and I will tell you how."}]},{"type":"collect","target":"coal","amount":5,"label":"Bring five coal as an offering"}],"dialogue":{"choice":[{"who":"npc","text":"The fire accepts your offering. Now: the oath. Say it with me, and be Kindled. Or leave, and be cold."}]},"choices":[{"id":"swear","label":"Swear the Kindled oath (and keep your fingers crossed).","flags":{"swore_oath":true},"dialogue":[{"who":"npc","text":"Kindled! Welcome, spark. Soon we wake the Emberwright, and the debt is paid in full."}]},{"id":"refuse","label":"Refuse the oath and walk out.","flags":{"refused_oath":true},"dialogue":[{"who":"npc","text":"Cold, then. The fire will remember your face."}]}]},{"id":"kessa","journal":"On the way out of the shrine an initiate called Kessa Emberly whispered that she would meet me at the Kindled’s kiln camp, east of Emberspire, where nobody listens.","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000005","amount":1,"label":"Meet Kessa Emberly at the kiln camp east of Emberspire","dialogue":[{"who":"npc","text":"I joined because I believed the story. I still do. But Tamber is not waiting for the debt. He is building a Herald, a golem of bellows and basalt, to blow the Emberwright awake."},{"who":"npc","text":"If he wakes it angry, Emberspire burns. Tell the Anvilhall. Please."}]}]},{"id":"assay","journal":"Kessa says Tamber is building a Herald, a bellows-golem, to force the Emberwright awake. Before I tell Kade, Assayer Doran Pike by the Emberspire market should hear about this “stolen heat”.","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000004","amount":1,"label":"Tell Assayer Pike about the Emberwright","dialogue":[{"who":"npc","text":"Heat from below. Hm. My furnace readings have been falling for ten years, a hair at a time."},{"who":"npc","text":"I assumed I was getting old. I might also be right. Tell Kade I want to assay the vents."}]}]}],"cutscenes":{"shrine":{"name":"The Cinder Shrine","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000003","distance":5,"height":2.2,"angle":30}},{"title":"The Cinder Shrine","subtitle":"The scrubland north-west of Emberspire","ms":2400},{"say":{"who":"npc","name":"Tamber the Kindled","text":"The fire never goes out here. We feed it, and it remembers. Come closer, spark."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000003","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"herald":{"name":"The Herald","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000001","distance":5,"height":2.2,"angle":30}},{"title":"Bellows and basalt","subtitle":"The Anvilhall, Emberspire","ms":2400},{"say":{"who":"npc","name":"Forgemistress Oriel Kade","text":"A golem built to wake a god. Under my forge. I need to sit down. On an anvil. They are very comfortable."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000001","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"herald"},"journalDone":"Wearing the Kindled sigil, I heard Tamber’s story of the Emberwright, the fire chained under Emberspire. Kessa Emberly warned me that Tamber is building a Herald to wake it by force. Assayer Pike has noticed the forges’ heat falling for years.","journalVariants":[{"ifFlags":{"swore_oath":true},"text":"I swore the Kindled oath, fingers crossed."},{"ifFlags":{"refused_oath":true},"text":"I refused the Kindled oath and walked out."}],"gold":400,"xp":{"smithing":6000,"mining":5000,"firemaking":3000},"lamps":[{"perLevel":10,"minLevel":10,"label":"Kindled lamp"}],"unlocks":[{"type":"flag","id":"forge.herald_known","label":"Emberspire knows of the Herald"},{"type":"dialogue","id":"dialogue.forge-tamber-sworn","label":"Tamber greets a spark","npc":"a3c0a000-0003-4000-8000-000000000003","ifFlags":{"swore_oath":true},"lines":[{"who":"npc","text":"Spark! The fire asks after you. Sit, warm your hands. Soon the debt is paid."}]},{"type":"dialogue","id":"dialogue.forge-tamber-cold","label":"Tamber remembers your face","npc":"a3c0a000-0003-4000-8000-000000000003","ifFlags":{"refused_oath":true},"lines":[{"who":"npc","text":"The cold one returns. The fire remembers you. It is not fond."}]}]}$q$::jsonb);
select eldervale_private.quest_arc_put('a3c0b000-0003-4000-8000-000000000003',$q${"chain":"arc-forge","order":3,"published":true,"objectives":[],"key":"arc-forge-3","name":"Assay of Embers","questPoints":2,"difficulty":"Intermediate","length":"Medium","giver":"a3c0a000-0003-4000-8000-000000000004","icon":"ironBar","requirements":{"quests":["arc-forge-2","arc-crown-2"],"skills":{"smithing":{"level":30,"boostable":false},"mining":{"level":30,"boostable":false}}},"description":"Assayer Doran Pike wants to measure the heat rising from the vents east of Emberspire. If the Emberwright is real, the numbers will say so.","dialogue":{"offer":[{"who":"npc","text":"Numbers do not lie. People do. Forgemistresses, occasionally."},{"who":"npc","text":"I need assay rods, three iron bars, and readings from the three vents by the ember hound run. The hounds will object."},{"who":"player","text":"I’ll bring you your numbers."}],"progress":[{"who":"npc","text":"Rods, vents, hounds. In that order is traditional."}],"complete":[{"who":"npc","text":"There. Written down, it is just a number. Out loud, it is a hundred years of theft."},{"who":"npc","text":"Thank you. I think. Here, for the rods and the bites."}]},"branchDialogue":[{"stage":"complete","ifFlags":{"kept_silent":true},"lines":[{"who":"npc","text":"So we keep it between us for now. The numbers will wait. They are patient. I am less so."},{"who":"npc","text":"Here, for the rods and the bites."}]}],"stages":[{"id":"rods","journal":"Assayer Doran Pike wants to measure the heat rising from the vents east of Emberspire. He needs three iron bars to make assay rods.","npc":"a3c0a000-0003-4000-8000-000000000004","objectives":[{"type":"collect","target":"ironBar","amount":3,"label":"Bring Pike three iron bars for assay rods"}],"dialogue":{"advance":[{"who":"npc","text":"Good iron. Push one into each vent by the ember hound run, east of town, and read the colour it turns."}]}},{"id":"vents","journal":"Pike gave me three assay rods to push into the vents by the ember hound run, east of Emberspire.","objectives":[{"type":"visit","x":326,"z":244,"radius":3,"amount":1,"label":"Assay the western vent"},{"type":"visit","x":347,"z":249,"radius":3,"amount":1,"label":"Assay the eastern vent"},{"type":"visit","x":338,"z":265,"radius":3,"amount":1,"label":"Assay the southern vent"}]},{"id":"hounds","journal":"The rods turned white in every vent. Then the ember hounds came: someone has been feeding them coal by the vents, and they treat the heat as theirs.","onEnter":{"cutscene":"vents"},"objectives":[{"type":"event","event":"death","targets":["a3c0a000-0003-4000-9000-000000000002","a3c0a000-0003-4000-9000-000000000003","a3c0a000-0003-4000-9000-000000000004"],"amount":3,"label":"Fight off the ash-fed ember hounds"}]},{"id":"samples","journal":"With the hounds gone I can chip some ember-glass from around the vents for Pike to compare with the Anvilhall’s furnace slag.","objectives":[{"type":"xp","skill":"mining","amount":250,"label":"Chip ember-glass samples (Mining XP)"}]},{"id":"verdict","journal":"I brought Pike the readings and samples. The heat under the scrubland and the heat in the Anvilhall’s furnaces are the same heat: drawn up by old iron channels the guild laid a century ago. Kade’s guild records must show them.","npc":"a3c0a000-0003-4000-8000-000000000004","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000004","amount":1,"label":"Hear Pike’s verdict"}],"dialogue":{"choice":[{"who":"npc","text":"The Anvilhall drinks the Emberwright’s heat. And the guild records have known for a hundred years. Kade has those records."},{"who":"npc","text":"Do we put this in front of her, or keep it quiet until we know what the Kindled will do?"}]},"choices":[{"id":"confront","label":"Kade deserves to see the numbers. Now.","flags":{"confronted_kade":true},"dialogue":[{"who":"npc","text":"Then go. I will be here, recalculating my will."}]},{"id":"silent","label":"Keep it quiet until we know Tamber’s plan.","flags":{"kept_silent":true},"dialogue":[{"who":"npc","text":"Quiet it is. Numbers keep. Tell Kade only that the vents are hot."}]}]},{"id":"forgemistress","journal":"I have decided what to tell Forgemistress Kade. I should speak to her at the Anvilhall, then return to Pike.","objectives":[{"type":"talk","target":"a3c0a000-0003-4000-8000-000000000001","amount":1,"label":"Speak to Forgemistress Kade","dialogue":[{"who":"npc","text":"I know what the vents say. I have known since I took the hammer. Every forgemistress is told on her first day, and sworn to say nothing."},{"who":"npc","text":"I am tired of saying nothing."}]}]}],"cutscenes":{"vents":{"name":"The vents","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000004","distance":5,"height":2.2,"angle":30}},{"title":"The ember hound run","subtitle":"East of Emberspire","ms":2400},{"say":{"who":"npc","name":"Assayer Doran Pike","text":"(Pike’s note, pinned to the rod) White means very hot. If the rod is white and the hounds are near, run first and assay later."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000004","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]},"numbers":{"name":"A hundred years","steps":[{"fade":"in","ms":700,"shot":{"around":"a3c0a000-0003-4000-8000-000000000004","distance":5,"height":2.2,"angle":30}},{"title":"The assay","subtitle":"Emberspire market","ms":2400},{"say":{"who":"npc","name":"Assayer Doran Pike","text":"Same heat, same channels, same signature. The Emberwright is real, and Emberspire has been drinking it dry."},"shot":{"around":"a3c0a000-0003-4000-8000-000000000004","distance":3.4,"height":1.8,"angle":35}},{"fade":"out","ms":600}]}},"onComplete":{"cutscene":"numbers"},"journalDone":"I assayed the vents by the ember hound run for Doran Pike. Their heat is the Anvilhall’s heat: for a hundred years the guild has drawn its fire from the sleeping Emberwright through old iron channels, and every forgemistress has known.","journalVariants":[{"ifFlags":{"confronted_kade":true},"text":"I put the numbers in front of Kade."},{"ifFlags":{"kept_silent":true},"text":"Pike and I kept the numbers quiet for now."}],"gold":600,"xp":{"mining":7000,"smithing":6000,"strength":4000},"lamps":[{"perLevel":10,"minLevel":15,"label":"Assayer’s lamp"}],"unlocks":[{"type":"flag","id":"forge.debt_proven","label":"The Emberwright’s debt is proven"},{"type":"dialogue","id":"dialogue.forge-pike-3","label":"Pike’s new hobby","npc":"a3c0a000-0003-4000-8000-000000000004","lines":[{"who":"npc","text":"I assay the vents every morning now. They are cooling, a hair a day. I have started talking to them. They do not answer. Yet."}]}]}$q$::jsonb);

commit;
